package org.researchdock.mobile;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.concurrent.*;
/** Private, offline visual PDF reader. Receives a cache hash, never a remote URL or token. */
public class PdfReaderActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile int generation=0;private int page=0,total=0;private volatile boolean loading;
 private String id,name;private SharedPreferences prefs;private PdfPageView image;private Button previous,next,pageButton;private TextView message;private SeekBar slider;private float[] initial;
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(13);b.setTextColor(Color.rgb(31,105,82));b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);id=getIntent().getStringExtra("asset_id");name=getIntent().getStringExtra("name");if(id==null||!id.matches("[a-f0-9]{64}")||!new File(getFilesDir(),"asset-"+id).isFile()){Toast.makeText(this,"PDF 缓存不存在，请重新下载",Toast.LENGTH_LONG).show();finish();return;}if(name==null||name.isEmpty())name="PDF 原件.pdf";
  prefs=getSharedPreferences("reader",MODE_PRIVATE);String key="pdf:"+id+":";page=Math.max(0,prefs.getInt(key+"page",0));initial=new float[]{prefs.getFloat(key+"zoom",1),prefs.getFloat(key+"cx",.5f),prefs.getFloat(key+"cy",0),prefs.getBoolean(key+"whole",false)?1:0};
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(247,248,244));LinearLayout top=new LinearLayout(this);top.addView(button("‹ 返回",this::finish),new LinearLayout.LayoutParams(0,dp(46),1));top.addView(button("适宽",()->image.fit(false)),new LinearLayout.LayoutParams(0,dp(46),1));top.addView(button("整页",()->image.fit(true)),new LinearLayout.LayoutParams(0,dp(46),1));top.addView(button("其他应用",this::external),new LinearLayout.LayoutParams(0,dp(46),1));root.addView(top);
  TextView title=new TextView(this);title.setText(name);title.setTextSize(14);title.setMaxLines(2);title.setPadding(dp(14),dp(6),dp(14),dp(6));root.addView(title);image=new PdfPageView(this);root.addView(image,new LinearLayout.LayoutParams(-1,0,1));
  message=new TextView(this);message.setTextSize(11);message.setPadding(dp(12),dp(5),dp(12),dp(3));root.addView(message);slider=new SeekBar(this);slider.setMinimumHeight(dp(40));slider.setContentDescription("PDF 页码进度");slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int v,boolean user){if(user)pageButton.setText((v+1)+" / "+total+" 页");}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){load(s.getProgress(),null);}});root.addView(slider);
  LinearLayout footer=new LinearLayout(this);previous=button("上一页",()->load(page-1,null));pageButton=button("页码",this::jump);next=button("下一页",()->load(page+1,null));for(Button b:new Button[]{previous,pageButton,next})footer.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(footer);setContentView(root);load(page,initial);
 }
 private void controls(){previous.setEnabled(!loading&&page>0);next.setEnabled(!loading&&total>0&&page+1<total);slider.setEnabled(!loading&&total>1);pageButton.setEnabled(!loading&&total>0);if(total>0){pageButton.setText((page+1)+" / "+total+" 页");slider.setMax(total-1);slider.setProgress(page);}}
 private void save(){if(prefs==null||total==0||image==null)return;String key="pdf:"+id+":";SharedPreferences.Editor edit=prefs.edit().putInt(key+"page",page);float[] v=image.position();if(v!=null)edit.putFloat(key+"zoom",v[0]).putFloat(key+"cx",v[1]).putFloat(key+"cy",v[2]).putBoolean(key+"whole",v[3]>0);edit.apply();}
 private void load(int requested,float[] restore){if(loading)return;float[] carry=restore;if(carry==null&&total>0){carry=image.position();if(carry!=null)carry[2]=0;}final float[] display=carry;save();loading=true;controls();message.setText("正在显示 PDF…");final int ticket=++generation;final int width=Math.max(1080,getResources().getDisplayMetrics().widthPixels);
  worker.execute(()->{Bitmap bitmap=null;try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(new File(getFilesDir(),"asset-"+id),ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){int count=renderer.getPageCount();if(count<1)throw new IOException();int number=Math.max(0,Math.min(count-1,requested));try(PdfRenderer.Page p=renderer.openPage(number)){double ratio=Math.min(Math.min(width*2.0/p.getWidth(),4096.0/p.getHeight()),Math.sqrt(6000000.0/((double)p.getWidth()*p.getHeight())));bitmap=Bitmap.createBitmap(Math.max(1,(int)(p.getWidth()*ratio)),Math.max(1,(int)(p.getHeight()*ratio)),Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);p.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}Bitmap result=bitmap;runOnUiThread(()->{if(ticket!=generation||isFinishing()||isDestroyed()){result.recycle();return;}page=number;total=count;image.page(result,display);loading=false;controls();message.setText("双指缩放 · 拖动查看 · 双击放大 · 点击页码跳转");save();});
  }catch(Exception|OutOfMemoryError e){if(bitmap!=null)bitmap.recycle();runOnUiThread(()->{if(ticket==generation&&!isFinishing()){loading=false;controls();message.setText("此 PDF 暂无法显示，可用其他应用打开；返回后也可重新下载原件。");}});}});
 }
 private void jump(){EditText input=new EditText(this);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);input.setHint("1–"+total);input.setSelectAllOnFocus(true);input.setText(String.valueOf(page+1));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("跳转页码 · 共 "+total+" 页").setView(input).setPositiveButton("跳转",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{int n=Integer.parseInt(input.getText().toString().trim());if(n<1||n>total)throw new NumberFormatException();dialog.dismiss();load(n-1,null);}catch(NumberFormatException e){input.setError("请输入 1 到 "+total+" 的页码");}}));dialog.show();}
 private void external(){String filename=name.replace('/','_');if(!filename.toLowerCase(java.util.Locale.ROOT).endsWith(".pdf"))filename+=".pdf";android.net.Uri uri=new android.net.Uri.Builder().scheme("content").authority(getPackageName()+".attachments").appendPath("asset").appendPath(id).appendPath(filename).build();Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/pdf").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(intent,"选择 PDF 阅读应用"));}catch(ActivityNotFoundException e){Toast.makeText(this,"手机没有可用的外部 PDF 阅读应用",Toast.LENGTH_LONG).show();}}
 @Override protected void onPause(){save();super.onPause();}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();if(image!=null)image.release();super.onDestroy();}
}
